const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/change_order_packages',
  qs: {
    project_id: 'SOME_INTEGER_VALUE',
    contract_id: 'SOME_INTEGER_VALUE',
    'filters[id]': 'SOME_ARRAY_VALUE',
    'filters[created_at]': 'SOME_STRING_VALUE',
    'filters[updated_at]': 'SOME_STRING_VALUE',
    'filters[reviewed_at]': 'SOME_STRING_VALUE',
    'filters[due_date]': 'SOME_STRING_VALUE',
    'filters[include_deleted]': 'SOME_STRING_VALUE',
    'filters[invoiced_date]': 'SOME_STRING_VALUE',
    'filters[paid_date]': 'SOME_STRING_VALUE',
    'filters[signed_change_order_received_date]': 'SOME_STRING_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  },
  headers: {Authorization: 'Bearer REPLACE_BEARER_TOKEN'}
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/change_order_packages?project_id=SOME_INTEGER_VALUE&contract_id=SOME_INTEGER_VALUE&filters%5Bid%5D=SOME_ARRAY_VALUE&filters%5Bcreated_at%5D=SOME_STRING_VALUE&filters%5Bupdated_at%5D=SOME_STRING_VALUE&filters%5Breviewed_at%5D=SOME_STRING_VALUE&filters%5Bdue_date%5D=SOME_STRING_VALUE&filters%5Binclude_deleted%5D=SOME_STRING_VALUE&filters%5Binvoiced_date%5D=SOME_STRING_VALUE&filters%5Bpaid_date%5D=SOME_STRING_VALUE&filters%5Bsigned_change_order_received_date%5D=SOME_STRING_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
    Headers =
    {
        { "Authorization", "Bearer REPLACE_BEARER_TOKEN" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

